# test_moving_average.py
import pytest

from your_module import moving_average  # Replace with the actual module name


@pytest.mark.parametrize(
    ("data", "window", "expected"),
    [
        ([1, 2, 3, 4], 2, [1.5, 2.5, 3.5]),
        ([1, 2, 3, 4, 5], 3, [2.0, 3.0, 4.0]),
        ([-1, 1, -1, 1], 2, [0.0, 0.0, 0.0]),
        ([0.1, 0.2, 0.3], 2, [0.15, 0.25]),
    ],
)
def test_moving_average_happy_path(data, window, expected):
    assert moving_average(data, window) == pytest.approx(expected)


def test_window_size_one_returns_each_value():
    assert moving_average([5, -1, 0], 1) == [5.0, -1.0, 0.0]


def test_window_equal_to_data_length_returns_single_average():
    assert moving_average([2, 4, 6, 8], 4) == [5.0]


@pytest.mark.parametrize(
    ("data", "window"),
    [
        ([1, 2, 3], 0),
        ([1, 2, 3], -1),
        ([1, 2, 3], -10),
        ([1, 2, 3], 4),
        ([], 1),
        ([], 0),
    ],
)
def test_invalid_window_or_empty_data_returns_empty_list(data, window):
    assert moving_average(data, window) == []


def test_input_list_is_not_mutated():
    data = [1, 2, 3, 4]
    original = data.copy()

    moving_average(data, 2)

    assert data == original


@pytest.mark.parametrize(
    ("data", "window"),
    [
        ([1, "2", 3], 2),
        (["a"], 1),
        ([object()], 1),
    ],
)
def test_non_numeric_data_raises_type_error(data, window):
    with pytest.raises(TypeError):
        moving_average(data, window)


@pytest.mark.parametrize("bad_window", [1.5, "2", None])
def test_non_integer_window_raises_type_error(bad_window):
    with pytest.raises(TypeError):
        moving_average([1, 2, 3], bad_window)


def test_none_data_raises_type_error():
    with pytest.raises(TypeError):
        moving_average(None, 1)
